235	/**
236	 * Finds all secret files in a directory up to a certain depth.
237	 * Default is shallow scan (depth 1) for performance.
238	 */
239	export async function findSecretFiles(
240	  baseDir: string,
241	  maxDepth = 1,
242	): Promise<string[]> {
243	  const secrets: string[] = [];
244	  const skipDirs = new Set([
245	    'node_modules',
246	    '.git',
247	    '.venv',
248	    '__pycache__',
249	    'dist',
250	    'build',
251	    '.next',
252	    '.idea',
253	    '.vscode',
254	  ]);
255	
256	  async function walk(dir: string, depth: number) {
257	    if (depth > maxDepth) return;
258	    try {
259	      const entries = await fs.readdir(dir, { withFileTypes: true });
260	      for (const entry of entries) {
261	        const fullPath = path.join(dir, entry.name);
262	        if (entry.isDirectory()) {
263	          if (!skipDirs.has(entry.name)) {
264	            await walk(fullPath, depth + 1);
265	          }
266	        } else if (entry.isFile()) {
267	          if (isSecretFile(entry.name)) {
268	            secrets.push(fullPath);
269	          }
270	        }
271	      }
272	    } catch {
273	      // Ignore read errors
274	    }
275	  }
276	
277	  await walk(baseDir, 1);
278	  return secrets;
279	}
